import{_ as t,o,c as s,a2 as a}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"Paramètres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/settings.md","filePath":"fr/guide/settings.md"}'),r={name:"fr/guide/settings.md"};function n(i,e,c,l,u,d){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h1><p>Les <strong>Paramètres</strong> (<code>/settings/…</code>) sont découpés en cinq sections, en onglets sur ordinateur et listées dans la page <strong>Plus</strong> sur mobile :</p><table tabindex="0"><thead><tr><th>Section</th><th>Adresse</th></tr></thead><tbody><tr><td><a href="#compte">Compte</a></td><td><code>/settings/account</code></td></tr><tr><td><a href="#securite">Sécurité</a></td><td><code>/settings/security</code></td></tr><tr><td><a href="#comptes-gmail">Comptes Gmail</a></td><td><code>/settings/gmail</code></td></tr><tr><td><a href="#notifications-webhooks">Notifications &amp; webhooks</a></td><td><code>/settings/notifications</code></td></tr><tr><td><a href="#donnees">Données</a></td><td><code>/settings/data</code></td></tr></tbody></table><hr><h2 id="compte" tabindex="-1">Compte <a class="header-anchor" href="#compte" aria-label="Permalink to &quot;Compte&quot;">​</a></h2><ul><li><strong>Profil</strong> : avatar, nom, email, et l&#39;espace occupé par vos archives (« Archives : X utilisés sur Y », quota fixé par l&#39;administrateur).</li><li><strong>Langue et apparence</strong> : <strong>Langue</strong> (français / anglais) et <strong>Thème</strong> (<strong>Système</strong>, <strong>Clair</strong>, <strong>Sombre</strong>). La langue et le mode sombre sont aussi dans le menu de l&#39;avatar.</li><li><strong>Lecture</strong> : <ul><li><strong>Afficher les images distantes</strong> : désactivé par défaut, car ces images servent souvent à savoir quand vous ouvrez un mail. Un bouton « Afficher » reste disponible dans chaque mail.</li><li><strong>Raccourcis clavier à une touche</strong> : active les <a href="./mails.html#raccourcis-clavier">raccourcis de Mails</a> (<code>j</code>/<code>k</code>, <code>e</code>, <code>#</code>, <code>r</code>, <code>u</code>, <code>/</code>). À désactiver si vous utilisez une commande vocale.</li></ul></li></ul><hr><h2 id="securite" tabindex="-1">Sécurité <a class="header-anchor" href="#securite" aria-label="Permalink to &quot;Sécurité&quot;">​</a></h2><h3 id="mot-de-passe" tabindex="-1">Mot de passe <a class="header-anchor" href="#mot-de-passe" aria-label="Permalink to &quot;Mot de passe&quot;">​</a></h3><p>Comptes locaux uniquement (un compte Google ou SSO n&#39;a pas de mot de passe Nid) : <strong>Mot de passe actuel</strong>, <strong>Nouveau mot de passe</strong> (8 caractères minimum) et sa confirmation, puis <strong>Changer le mot de passe</strong>. Vos autres sessions ouvertes sont déconnectées.</p><p>Mot de passe oublié : sur l&#39;écran de connexion, <strong>Mot de passe oublié ?</strong> envoie un lien valable 1 heure (si l&#39;instance a un serveur SMTP, voir <a href="./../installation/configuration.html#e-mail-smtp">Configuration</a>). Sinon, demandez à un administrateur de le réinitialiser (<a href="./admin.html#utilisateurs">Administration</a>).</p><h3 id="authentification-a-deux-facteurs-2fa" tabindex="-1">Authentification à deux facteurs (2FA) <a class="header-anchor" href="#authentification-a-deux-facteurs-2fa" aria-label="Permalink to &quot;Authentification à deux facteurs (2FA)&quot;">​</a></h3><ol><li>Cliquez sur <strong>Configurer la 2FA</strong></li><li>Scannez le QR code avec votre application d&#39;authentification (Google Authenticator, Aegis, Authy…), ou saisissez la clé affichée</li><li>Saisissez le <strong>Code à 6 chiffres</strong> puis <strong>Vérifier et activer</strong></li></ol><p>Une fois activée, un code est demandé à chaque connexion, y compris avec Google ou un autre fournisseur (SSO). Pour la désactiver, saisissez un code puis <strong>Désactiver la 2FA</strong>.</p><h3 id="liens-de-partage" tabindex="-1">Liens de partage <a class="header-anchor" href="#liens-de-partage" aria-label="Permalink to &quot;Liens de partage&quot;">​</a></h3><p>Nombre de liens de partage actifs vers vos mails archivés, avec le lien <strong>Gérer les liens de partage dans Archives</strong> (onglet <a href="./archives.html#onglet-partages">Partages</a>).</p><hr><h2 id="comptes-gmail" tabindex="-1">Comptes Gmail <a class="header-anchor" href="#comptes-gmail" aria-label="Permalink to &quot;Comptes Gmail&quot;">​</a></h2><p>Chaque compte connecté affiche :</p><ul><li>son état : <strong>Synchronisé</strong>, <strong>Action requise</strong> (Google a retiré l&#39;accès de Nid : reconnectez le compte pour reprendre la synchronisation et les sauvegardes) ou <strong>Déconnecté</strong> ;</li><li><strong>Synchronisation</strong> : « Dernière synchro … », nombre de mails dans Gmail, bouton <strong>Synchroniser maintenant</strong> ;</li><li><strong>Sauvegarde NAS</strong> : <strong>Sauvegarde automatique</strong> (sauvegarde sur le NAS les nouveaux mails du compte) et sa <strong>Fréquence</strong> : Toutes les heures, Toutes les 6 heures, Une fois par jour ;</li><li><strong>Reconnecter avec Google</strong> et <strong>Déconnecter</strong>.</li></ul><p><strong>Déconnecter</strong> demande confirmation : Nid arrête la synchronisation et les sauvegardes de ce compte, mais ses archives restent sur le NAS et dans Nid. Les pages qui ont besoin de Gmail (Vue d&#39;ensemble, Mails, Nettoyage, Règles) affichent alors « … est déconnecté » avec <strong>Reconnecter dans Paramètres</strong> ; <a href="./archives.html">Archives</a> reste consultable.</p><p><strong>Ajouter un compte Gmail</strong> connecte un nouveau compte, dans la limite affichée (« N / max comptes »). Accès demandés : <code>gmail.modify</code>, <code>gmail.labels</code>.</p><hr><h2 id="notifications-webhooks" tabindex="-1">Notifications &amp; webhooks <a class="header-anchor" href="#notifications-webhooks" aria-label="Permalink to &quot;Notifications &amp; webhooks&quot;">​</a></h2><p>Préférences par événement (in-app, toast) et webhooks vers Discord, Slack, ntfy ou une URL à vous : voir <a href="./notifications.html">Notifications</a>.</p><hr><h2 id="donnees" tabindex="-1">Données <a class="header-anchor" href="#donnees" aria-label="Permalink to &quot;Données&quot;">​</a></h2><p>Les imports et l&#39;export portent sur le compte Gmail actif.</p><h3 id="importer-un-fichier-mbox" tabindex="-1">Importer un fichier mbox <a class="header-anchor" href="#importer-un-fichier-mbox" aria-label="Permalink to &quot;Importer un fichier mbox&quot;">​</a></h3><p>Export Google Takeout ou autre client mail, ajouté aux archives du compte (libellés Gmail conservés). Cliquez sur <strong>Choisir un fichier .mbox</strong> ; l&#39;import se suit dans <a href="./activity.html">Activité</a>.</p><div class="tip custom-block"><p class="custom-block-title">Google Takeout</p><ol><li>Allez sur <a href="https://takeout.google.com" target="_blank" rel="noreferrer">takeout.google.com</a></li><li>Sélectionnez uniquement <strong>Gmail</strong>, au format <strong>mbox</strong></li><li>Téléchargez l&#39;archive et importez le fichier <code>.mbox</code> dans Nid</li></ol></div><h3 id="importer-depuis-un-serveur-imap" tabindex="-1">Importer depuis un serveur IMAP <a class="header-anchor" href="#importer-depuis-un-serveur-imap" aria-label="Permalink to &quot;Importer depuis un serveur IMAP&quot;">​</a></h3><p>Copie les mails d&#39;une autre boîte (Outlook, Fastmail…) dans les archives du compte. Champs : <strong>Serveur</strong>, <strong>Port</strong>, <strong>Identifiant</strong>, <strong>Mot de passe</strong>, <strong>Dossier</strong>, <strong>Nombre maximal de mails</strong>, <strong>Connexion chiffrée (TLS)</strong>, puis <strong>Lancer l&#39;import</strong>. Le mot de passe n&#39;est pas conservé.</p><div class="warning custom-block"><p class="custom-block-title">Mot de passe d&#39;application</p><p>De nombreux fournisseurs (Google, Outlook, Yahoo) exigent un <strong>mot de passe d&#39;application</strong> plutôt que votre mot de passe habituel.</p></div><h3 id="exporter-les-archives" tabindex="-1">Exporter les archives <a class="header-anchor" href="#exporter-les-archives" aria-label="Permalink to &quot;Exporter les archives&quot;">​</a></h3><p><strong>Exporter (.mbox)</strong> : toutes les archives du compte dans un fichier .mbox, lisible par Thunderbird ou Apple Mail.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Vos règles et webhooks dans un fichier JSON, pour les sauvegarder ou les reprendre sur une autre instance : <strong>Exporter la configuration</strong> / <strong>Importer une configuration</strong>.</p><h3 id="mes-donnees-rgpd" tabindex="-1">Mes données (RGPD) <a class="header-anchor" href="#mes-donnees-rgpd" aria-label="Permalink to &quot;Mes données (RGPD)&quot;">​</a></h3><p><strong>Exporter mes données</strong> : tout ce que Nid conserve sur vous dans un fichier JSON (profil, comptes Gmail, règles, métadonnées des archives, journal d&#39;activité…). Le contenu des mails s&#39;exporte en .mbox (ci-dessus) ; les secrets (mots de passe, jetons) sont exclus.</p><h3 id="supprimer-mon-compte" tabindex="-1">Supprimer mon compte <a class="header-anchor" href="#supprimer-mon-compte" aria-label="Permalink to &quot;Supprimer mon compte&quot;">​</a></h3><p>Saisissez votre mot de passe (ou, pour un compte Google/SSO, votre adresse e-mail), puis <strong>Supprimer définitivement mon compte</strong> et confirmez. Votre compte, vos comptes Gmail connectés, vos archives et vos règles sont supprimés de Nid ; rien n&#39;est supprimé dans Gmail. Le dernier administrateur de l&#39;instance ne peut pas supprimer son compte.</p>',42)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
